  var FIT = 0.9, DOCK = [38, 24];                  // the live Reliquary's: the wheel against its anchor, and the reading dock's radius (desktop, phone), px
  var P_OUT = 236 / 1.35, P_IN = 364 / 1.35;       // seconds a turn: the rim and the halo (clockwise), the collar and the leaves (the other way)
  var R_ORB = 0.6, R_TRUTH = 302 / 360 * 1.15 * 1.16, HS_T = 1.15 * 1.16;
  var clamp = function (x, a, b) { return x < a ? a : x > b ? b : x; };
  var lerp = function (a, b, t) { return a + (b - a) * t; };
