  var KEYS = Object.keys(MAN.pal[palName()].lod).sort(function (a, b) { return a - b; }), NK = KEYS.length;
  var FORCE = (/[?&]lod=(\d+)/.exec(QS) || [])[1] || "";
  var BLEND = !/[?&]blend=0/.test(QS), HZQ = +(/[?&]hz=(\d+)/.exec(QS) || [])[1] || 0;   // ?hz=N: turn no faster than N times a second (a test switch)
  var PARA = !/[?&]para=0/.test(QS);
  // the slow turns: turned by the compositor where the browser can (Web Animations on the individual "rotate" property: smooth at the screen's own rate, and no
  // main-thread work per frame), else written by the pacemaker. ?spin=p forces the pacemaker (20 times a second awake, 2 at rest), for comparing.
  // the compositor's turn moves in steps: N a second, all on one beat (each period is a whole number of steps, and every animation starts on the shared clock), so
  // the page is redrawn N times a second, not at every frame of the screen (144 here). At 30 a step moves the hero's outer ring a third of a pixel.
  var STEPS = +((/[?&]steps=(\d+)/.exec(QS) || [])[1] || 30);
  var REST_MS = 1000 * (+((/[?&]rest=(\d+)/.exec(QS) || [])[1] || 30));   // ?rest=N: the turn comes to rest N seconds after the last input (a test switch; 30 by default)
  var LITE_Q = /[?&]lite=1/.test(QS);
  var COMP = !/[?&]spin=p/.test(QS) && !!(window.CSS && CSS.supports && CSS.supports("rotate", "1deg")) && !!(Element.prototype.animate && document.timeline);
  var PLUS = BLEND && window.CSS && CSS.supports && CSS.supports("mix-blend-mode", "plus-lighter");   // exact addition where the browser has it, else screen

  // ---------- what the pages ask for, and where the wheel sits (the live gl.js's table) ----------
  var C = window.DV_CONTENT || {};
  var CH = C.chapters || [];
