  var T_BOOT = now();
  var SC = {                      // x, y: shares of the viewport; r: the radius as a share of its height (before FIT); neb: the aura; rings: the shield's strength; pts: the chapter points
    intro: { x: 0.5, y: 0.47, r: 0.3, neb: 0.7, rings: 1, pts: 1 },
    home: { anchor: true, neb: 0.75, rings: 1, pts: 1 },
    "home:index": { x: 0.5, y: 0.5, r: 0.6, neb: 0.8, rings: 0.16, pts: 0.55 },
    "home:four": { x: 0.88, y: 0.2, r: 0.16, neb: 0.75, rings: 0.6, pts: 1 },
    contents: { x: 0.9, y: 0.5, r: 0.46, neb: 0.8, rings: 0.4, pts: 1 },
    reader: { px: function (w, h) { return [w - (w < 700 ? 40 : 64), h - (w < 700 ? 40 : 64), (w < 700 ? DOCK[1] : DOCK[0]) / FIT]; }, neb: 0.3, rings: 0.9, pts: 1 },
    codex: { x: 0.82, y: 0.3, r: 0.22, neb: 0.7, rings: 0.75, pts: 1 },
    story: { x: 0.9, y: 0.5, r: 0.4, neb: 0.8, rings: 0.35, pts: 1 },
    tears: { x: 0.74, y: 0.45, r: 0.46, neb: 0.6, rings: 0, pts: 0, tear: 1 },
    powers: { x: 0.68, y: 0.42, r: 0.36, neb: 0.8, rings: 0, pts: 0 },
    about: { x: 0.85, y: 0.5, r: 0.36, neb: 0.5, rings: 0.4, pts: 1 },
    menu: { x: 0.84, y: 0.5, r: 0.42, neb: 0.6, rings: 0.55, pts: 1 },
  };
  var UNDOCKED = { intro: 1, home: 1, reader: 1, tears: 1, powers: 1, menu: 1 };   // on phones every other page docks the wheel in the corner
  var S = { cx: innerWidth / 2, cy: innerHeight * 0.47, r: innerHeight * 0.3 * FIT, glow: 0, rings: 0, pts: 0, tear: 0, draw: 0, rise: 0 };
  var page = "home", state = "home", menuOpen = false, reached = 0, poseTw = null, dirtyPose = false, HP = null, introPending = null, eclipseAt = 0;
